SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(t),'identity',to_jsonb(pg_identify_object('pg_trigger'::regclass,t.oid,0)),'relation',to_jsonb(pg_identify_object('pg_class'::regclass,t.tgrelid,0)),'function',to_jsonb(pg_identify_object('pg_proc'::regclass,t.tgfoid,0)),'constraint',CASE WHEN t.tgconstraint<>0 THEN to_jsonb(pg_identify_object('pg_constraint'::regclass,t.tgconstraint,0)) END,'constraint_relation',CASE WHEN t.tgconstrrelid<>0 THEN to_jsonb(pg_identify_object('pg_class'::regclass,t.tgconstrrelid,0)) END,'definition',pg_get_triggerdef(t.oid,false)) ORDER BY t.oid),'[]'::jsonb) AS payload FROM pg_trigger t WHERE t.tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture